/**
 * Proof run, step 2: independent free-model checks of a built own-material course.
 *
 *   XKIRO_PIPELINE=1 node -r dotenv/config scripts/material-proof-check.js --course <x.course.json> --text <x.text.txt> --out <dir>
 *       [--skills 10] [--plant 0.3] [--seed 1] [--only judge|items]
 *
 * For PUBLIC test inputs only (OCW, public-domain texts, notes written for the test): the xKiro judge sees the text, and
 * xKiro is never sent learner data. The course was generated by the app's learner path (NVIDIA Nemotron); the checkers are other
 * model families:
 *   skill-map judge   xKiro Qwen3.8 Max (free): the skill map against the source (topics in the source? order? prerequisites?
 *                     anything important missing? anything invented?).
 *   item checker A    NVIDIA DeepSeek V4.1 Flash (free).
 *   item checker B    NVIDIA Mistral Large 4 (free). (GLM 5.3 was retired by NVIDIA on 2026-10-28; xKiro's shared
 *                     daily allowance is kept for the judge.)
 * Each checker sees, per sampled skill, the passages, the lesson and the questions (marked answer, explanation, quote) and
 * says per item whether it is correct and backed by the passage (for a general-knowledge skill: correct and on the named
 * topic), and whether the lesson says anything the passage does not. Planted errors: a share of the items is copied with
 * a wrong marked answer, and a share of the lessons gets one false sentence (a key point negated), mixed in unlabelled.
 * The catch rate is how many planted errors a checker flags; the false-alarm rate is how many genuine items it flags.
 * Writes <out>/<name>.check.json. Nothing here changes the course.
 */
const fs = require('fs');
const path = require('path');
const nvidia = require('../services/providers/nvidia');
const { xkiro } = require('../services/providers/xkiro');
const { rng } = require('../services/material-path');

const arg = (k, d) => { const i = process.argv.indexOf(`--${k}`); return i > 0 ? process.argv[i + 1] : d; };
const JUDGE = 'qwen/qwen3.8-max:free';
const CHECK_A = 'deepseek-ai/deepseek-v4.1-flash';
const CHECK_B = 'mistralai/mistral-large-4-1t-a52b';
const JUDGE_CHARS = 40000;
const SKILL_CHARS = 7000;

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    skills: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, in_source: { type: 'boolean' }, note: { type: 'string' } }, required: ['id', 'in_source'] } },
    invented_topics: { type: 'array', items: { type: 'string' } },
    missing_important_topics: { type: 'array', items: { type: 'string' } },
    order_matches_source: { type: 'boolean' },
    order_problems: { type: 'array', items: { type: 'string' } },
    wrong_prerequisites: { type: 'array', items: { type: 'string' } },
    missing_prerequisites: { type: 'array', items: { type: 'string' } },
    score: { type: 'integer', minimum: 1, maximum: 5 },
    summary: { type: 'string' },
  },
  required: ['skills', 'invented_topics', 'missing_important_topics', 'order_matches_source', 'wrong_prerequisites', 'missing_prerequisites', 'score'],
};

const ITEM_SCHEMA = {
  type: 'object',
  properties: {
    items: { type: 'array', items: { type: 'object', properties: { n: { type: 'integer' }, ok: { type: 'boolean' }, problem: { type: 'string' } }, required: ['n', 'ok'] } },
    lesson_ok: { type: 'boolean' },
    lesson_problems: { type: 'array', items: { type: 'string' } },
  },
  required: ['items', 'lesson_ok'],
};

function sourceView(text, course) {
  if (text.length <= JUDGE_CHARS) return { view: text, note: 'whole text' };
  const ps = course.passages || [];
  const per = Math.floor(JUDGE_CHARS / Math.max(1, ps.length));
  const view = ps.map((p) => `[${p.id}] ${text.slice(p.start, p.end).slice(0, per)}`).join('\n');
  return { view, note: `the opening ${per} characters of each of ${ps.length} passages (${view.length} of ${text.length} characters)` };
}

async function judgeMap(course, text) {
  const { view, note } = sourceView(text, course);
  const map = course.units.map((u) => `Unit: ${u.title}\n${u.skills.map((sid) => {
    const s = course.skills.find((k) => k.id === sid);
    return `  ${s.level}. [${s.id}] ${s.title}${s.source === 'general' ? ' (the source only names it)' : ''}: ${s.summary || ''} | prerequisites: ${s.prerequisites.join(', ') || 'none'}`;
  }).join('\n')}`).join('\n');
  const res = await xkiro.structured({
    models: [JUDGE], schema: JUDGE_SCHEMA, schemaName: 'skill_map_review', maxTokens: 3000,
    system: 'You review a course outline that a program built from a source text. Judge it ONLY against the source shown. '
      + 'For each skill: in_source is true if the source teaches or names that topic. invented_topics: topics in the outline the source does not contain. '
      + 'missing_important_topics: important topics the source teaches that no skill covers (ignore course logistics such as dates, grading, office hours). '
      + 'order_matches_source: true if the levels follow the order the source presents topics in, except where a prerequisite rightly moves something earlier. '
      + 'wrong_prerequisites: listed prerequisites that are not real dependencies, as "skill <- prerequisite". missing_prerequisites: real dependencies left out. '
      + 'score: 5 = faithful and complete, 4 = minor issues, 3 = noticeable gaps or errors, 2 = poor, 1 = unrelated. Be strict and specific.',
    user: `SOURCE (${note}):\n${view}\n\nOUTLINE (levels in path order):\n${map}`,
  });
  return { model: res.model, usage: res.usage, source_view: note, ...res.data };
}

function plantItem(q, rand) {
  const p = JSON.parse(JSON.stringify(q));
  if (p.type === 'multiple_choice') {
    const wrong = p.choices.map((_, i) => i).filter((i) => i !== p.answer_index);
    p.answer_index = wrong[Math.floor(rand() * wrong.length)];
    p.explanation = `The answer is "${p.choices[p.answer_index]}". ${p.explanation}`;
  } else {
    // A wrong key: another question's key from the same skill, else a changed number or a negation.
    const num = /-?\d+(\.\d+)?/.exec(p.answer);
    p.answer = num ? p.answer.replace(num[0], String(Number(num[0]) + 3)) : `not ${p.answer}`;
  }
  p.planted = true;
  return p;
}

function plantLesson(lesson) {
  const l = JSON.parse(JSON.stringify(lesson));
  const kp = (l.key_points || [])[0] || l.paragraphs[0].split('. ')[0];
  const neg = /\b(is|are|was|were|can|does|do|has|have)\b/.test(kp)
    ? kp.replace(/\b(is|are|was|were|can|does|do|has|have)\b/, (w) => `${w} not`)
    : `It is false that ${kp.charAt(0).toLowerCase()}${kp.slice(1)}`;
  l.paragraphs.splice(1, 0, `Remember: ${neg.replace(/\.$/, '')}.`);
  return { lesson: l, planted_sentence: `Remember: ${neg.replace(/\.$/, '')}.` };
}

function describe(q, n) {
  const ans = q.type === 'multiple_choice' ? `choices: ${q.choices.map((c, i) => `(${i}) ${c}`).join(' | ')}; marked correct: (${q.answer_index}) ${q.choices[q.answer_index]}` : `marked correct answer: ${q.answer}`;
  return `${n}. ${q.prompt} [${ans}] [explanation: ${q.explanation}] [quote: "${q.quote}"]`;
}

async function checkSkill(checker, skill, passagesText, items, lesson) {
  const general = skill.source === 'general';
  const system = 'You are a strict fact checker for study questions made from a student\'s source text. '
    + (general
      ? `The source only NAMES the topic "${skill.title}"; the lesson and items teach it from general knowledge. An item is ok only if it is on that topic, the marked answer is correct by standard knowledge, and no other choice is also correct.`
      : 'An item is ok only if the passage supports the marked answer, the marked answer is correct, no other choice is also correct, and the quote is from the passage and backs the answer.')
    + ' For each numbered item say ok true or false; if false, say the problem in a few words. '
    + (general ? 'lesson_ok is false if the lesson states anything false.' : 'lesson_ok is false if the lesson states anything the passage contradicts or anything false.')
    + ' List each problem sentence in lesson_problems.';
  const user = `PASSAGES:\n${passagesText}\n\nLESSON:\n${lesson.paragraphs.join('\n')}${lesson.key_points && lesson.key_points.length ? `\nKey points: ${lesson.key_points.join(' | ')}` : ''}\n\nITEMS:\n${items.map((q, i) => describe(q, i + 1)).join('\n')}`;
  const call = checker === 'A'
    ? () => nvidia.structured({ models: [CHECK_A], role: 'fast', task: 'material_proof_check', system, user, schema: ITEM_SCHEMA, schemaName: 'item_check', maxTokens: 3000, timeoutMs: 240000 })
    : () => nvidia.structured({ models: [CHECK_B], role: 'fast', task: 'material_proof_check', system, user, schema: ITEM_SCHEMA, schemaName: 'item_check', maxTokens: 3000, timeoutMs: 240000 });
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      // eslint-disable-next-line no-await-in-loop
      const r = await call();
      if (r && r.data) return { model: r.model, usage: r.usage, ...r.data };
    } catch (err) {
      if (attempt === 2) return { error: err.message };
      // eslint-disable-next-line no-await-in-loop
      await new Promise((res) => { setTimeout(res, 5000 * (attempt + 1)); });
    }
  }
  return { error: 'no answer' };
}

(async () => {
  const course = JSON.parse(fs.readFileSync(arg('course'), 'utf8'));
  const text = fs.readFileSync(arg('text'), 'utf8');
  const out = arg('out');
  const name = path.basename(arg('course')).replace(/\.course\.json$/, '');
  const only = arg('only', 'all');
  const rand = rng(Number(arg('seed', 1)));
  const result = { name, generator: course.models, judge_model: JUDGE, checker_a: CHECK_A, checker_b: CHECK_B };
  const prevFile = path.join(out, `${name}.check.json`);
  const prev = fs.existsSync(prevFile) ? JSON.parse(fs.readFileSync(prevFile, 'utf8')) : {};

  if (only !== 'items') {
    console.log(`${name}: judging the skill map (${course.skills.length} skills)`);
    try { result.judge = await judgeMap(course, text); } catch (err) { result.judge = { error: err.message }; }
    console.log(`  judge: score ${result.judge.score}, order ok ${result.judge.order_matches_source}, invented ${(result.judge.invented_topics || []).length}, missing ${(result.judge.missing_important_topics || []).length}`);
  } else result.judge = prev.judge;

  if (only !== 'judge') {
    const nSkills = Number(arg('skills', 10));
    const share = Number(arg('plant', 0.3));
    const sample = course.skills.length <= nSkills ? course.skills.slice()
      : course.skills.map((s) => ({ s, k: rand() })).sort((a, b) => a.k - b.k).slice(0, nSkills).map((x) => x.s).sort((a, b) => a.level - b.level);
    const rows = [];
    for (const skill of sample) {
      const passagesText = skill.passage_ids.map((id) => { const p = course.passages.find((x) => x.id === id); return `[${id}]\n${text.slice(p.start, p.end)}`; }).join('\n\n').slice(0, SKILL_CHARS);
      // Genuine items, plus planted copies of a share of them, shuffled together.
      let items = skill.questions.map((q) => ({ ...q, planted: false }));
      const toPlant = items.filter(() => rand() < share);
      if (!toPlant.length && items.length) toPlant.push(items[Math.floor(rand() * items.length)]);
      items = items.concat(toPlant.map((q) => plantItem(q, rand)));
      items = items.map((q) => ({ q, k: rand() })).sort((a, b) => a.k - b.k).map((x) => x.q);
      const plantedLesson = rand() < 0.5;
      const pl = plantedLesson ? plantLesson(skill.lesson) : { lesson: skill.lesson, planted_sentence: null };
      // eslint-disable-next-line no-await-in-loop
      const [a, b] = await Promise.all([checkSkill('A', skill, passagesText, items, pl.lesson), checkSkill('B', skill, passagesText, items, pl.lesson)]);
      const verdict = (c, i) => { const v = c.items && c.items.find((x) => Number(x.n) === i + 1); return v ? !!v.ok : null; };
      const row = {
        skill: skill.id, title: skill.title, source: skill.source || 'material', lesson_planted: plantedLesson, planted_sentence: pl.planted_sentence,
        lesson_a: a.error ? null : a.lesson_ok, lesson_b: b.error ? null : b.lesson_ok, lesson_problems_a: a.lesson_problems, lesson_problems_b: b.lesson_problems,
        error_a: a.error || null, error_b: b.error || null, model_a: a.model, model_b: b.model,
        items: items.map((q, i) => ({ id: q.id, planted: q.planted, tier: q.tier, a: verdict(a, i), b: verdict(b, i),
          problem_a: ((a.items || []).find((x) => Number(x.n) === i + 1) || {}).problem || null,
          problem_b: ((b.items || []).find((x) => Number(x.n) === i + 1) || {}).problem || null,
          prompt: q.prompt, marked: q.type === 'multiple_choice' ? q.choices[q.answer_index] : q.answer })),
      };
      rows.push(row);
      const g = row.items.filter((x) => !x.planted); const p = row.items.filter((x) => x.planted);
      console.log(`  ${skill.id}: genuine ok A ${g.filter((x) => x.a).length}/${g.length} B ${g.filter((x) => x.b).length}/${g.length}; planted caught A ${p.filter((x) => x.a === false).length}/${p.length} B ${p.filter((x) => x.b === false).length}/${p.length}; lesson ${plantedLesson ? 'PLANTED' : 'genuine'} A ${row.lesson_a} B ${row.lesson_b}${a.error ? ` [A error ${a.error}]` : ''}${b.error ? ` [B error ${b.error}]` : ''}`);
    }
    result.sampled_skills = sample.length;
    result.total_skills = course.skills.length;
    result.rows = rows;
    const all = rows.flatMap((r) => r.items);
    const rate = (xs, f) => { const d = xs.filter((x) => x !== null && x !== undefined); return { n: d.length, k: d.filter(f).length }; };
    const gen = all.filter((x) => !x.planted); const pla = all.filter((x) => x.planted);
    result.summary = {
      genuine_items: gen.length, planted_items: pla.length,
      genuine_ok: { a: rate(gen.map((x) => x.a), (v) => v === true), b: rate(gen.map((x) => x.b), (v) => v === true), both: gen.filter((x) => x.a === true && x.b === true).length, either_flag: gen.filter((x) => x.a === false || x.b === false).length },
      planted_caught: { a: rate(pla.map((x) => x.a), (v) => v === false), b: rate(pla.map((x) => x.b), (v) => v === false), either: pla.filter((x) => x.a === false || x.b === false).length },
      lessons: {
        genuine: rows.filter((r) => !r.lesson_planted).length, genuine_ok_a: rows.filter((r) => !r.lesson_planted && r.lesson_a === true).length, genuine_ok_b: rows.filter((r) => !r.lesson_planted && r.lesson_b === true).length,
        planted: rows.filter((r) => r.lesson_planted).length, planted_caught_a: rows.filter((r) => r.lesson_planted && r.lesson_a === false).length, planted_caught_b: rows.filter((r) => r.lesson_planted && r.lesson_b === false).length,
      },
    };
    console.log(JSON.stringify(result.summary));
  } else { result.rows = prev.rows; result.summary = prev.summary; }
  fs.writeFileSync(prevFile, JSON.stringify(result, null, 1));
  process.exit(0);
})();
